-- A version 6 control database holding every record kind, written by the
-- version 6 server. Its reads, as that server answered them: records-v6-reads.json.
-- Both files then had the PR URL's number replaced by the word fixture.
CREATE TABLE records (key TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE telegram_deliveries (
 update_id INTEGER PRIMARY KEY, message_id INTEGER NOT NULL DEFAULT 0,
 text TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '', settled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE telegram_state (
 id INTEGER PRIMARY KEY CHECK(id=1), offset INTEGER NOT NULL DEFAULT 0,
 digest_at TEXT NOT NULL DEFAULT '');
PRAGMA user_version=6;
